	protected Target getTargetIfReadsPresent() {
		if (targetService == null) {
			return null;
		}
		Target target = targetService.getTarget(source.getTrace());
		if (target == null) {
			return null;
		}
		if (!DebuggerCoordinates.NOWHERE.view(source).target(target).isAliveAndReadsPresent()) {
			return null;
		}
		return target;
	}

