	internal class _Anon_Task_4 : Task
	{
		public _Anon_Task_4() : @base("Copy Into Program", true, true, false) {}

			/* @Override */
			public void run(TaskMonitor monitor)
    {
				try {
					executePlan(monitor);
					Swing.runLater(() => {
						setStatusText("");
						close();
					});
				}
				catch (Exception e) {
					Msg.error(this, "Error copying into program", e);
					setStatusText("Error: " + e.getMessage());
				}
			}
		
	}


	internal class _Anon_TaskListener_5 : TaskListener
	{

			/* @Override */
			public void taskCancelled(Task task) {
				lastTask.cancel(false);
			}

			/* @Override */
			public void taskCompleted(Task task) {
				lastTask.complete(null);
			}
		
	}

